<script setup>
import { computed, ref } from 'vue';

const props = defineProps({ items: { type: Array, default: () => [] }, reproduciendoId: { type: [Number, String], default: null }, completado: { type: Boolean, default: false } });
const emit = defineEmits(['reproducir', 'hablar', 'practicar']);

const leccion = ref(1);
const canasta = ref({ apple: 1, banana: 1 });
const frutaActiva = ref('strawberry');
const retoActual = ref(0);
const seleccionReto = ref([]);
const comprobado = ref(false);
const aciertos = ref(new Set());

const frutas = [
  { id: 'apple', singular: 'apple', plural: 'apples', es: 'manzana', icono: '🍎', color: 'red', sabor: 'crisp and sweet' },
  { id: 'banana', singular: 'banana', plural: 'bananas', es: 'banana', icono: '🍌', color: 'yellow', sabor: 'soft and sweet' },
  { id: 'orange', singular: 'orange', plural: 'oranges', es: 'naranja', icono: '🍊', color: 'orange', sabor: 'juicy and citrusy' },
  { id: 'strawberry', singular: 'strawberry', plural: 'strawberries', es: 'frutilla', icono: '🍓', color: 'red', sabor: 'sweet and slightly tart' },
  { id: 'grape', singular: 'grape', plural: 'grapes', es: 'uva', icono: '🍇', color: 'purple', sabor: 'small and juicy' },
  { id: 'watermelon', singular: 'watermelon', plural: 'watermelons', es: 'sandía', icono: '🍉', color: 'green outside, red inside', sabor: 'fresh and juicy' },
  { id: 'pineapple', singular: 'pineapple', plural: 'pineapples', es: 'ananá', icono: '🍍', color: 'yellow inside', sabor: 'sweet and tangy' },
  { id: 'peach', singular: 'peach', plural: 'peaches', es: 'durazno', icono: '🍑', color: 'orange and pink', sabor: 'soft and sweet' },
  { id: 'pear', singular: 'pear', plural: 'pears', es: 'pera', icono: '🍐', color: 'green', sabor: 'mild and juicy' },
  { id: 'cherry', singular: 'cherry', plural: 'cherries', es: 'cereza', icono: '🍒', color: 'red', sabor: 'small and sweet' },
];
const activa = computed(() => frutas.find((item) => item.id === frutaActiva.value));
const totalCanasta = computed(() => Object.values(canasta.value).reduce((total, cantidad) => total + cantidad, 0));
const pedido = computed(() => {
  const partes = Object.entries(canasta.value).filter(([, cantidad]) => cantidad > 0).map(([id, cantidad]) => {
    const fruta = frutas.find((item) => item.id === id); return `${cantidad === 1 ? 'one' : cantidad === 2 ? 'two' : cantidad === 3 ? 'three' : cantidad} ${cantidad === 1 ? fruta.singular : fruta.plural}`;
  });
  if (!partes.length) return 'My basket is empty.';
  if (partes.length === 1) return `I'd like ${partes[0]}, please.`;
  return `I'd like ${partes.slice(0, -1).join(', ')} and ${partes.at(-1)}, please.`;
});

const retos = [
  { icono: '🥤', nombre: 'Batido rojo', pedido: 'Two strawberries and one apple', ids: ['strawberry','strawberry','apple'], pista: '2 🍓 + 1 🍎' },
  { icono: '🏖️', nombre: 'Mezcla tropical', pedido: 'One pineapple, one banana and one orange', ids: ['pineapple','banana','orange'], pista: '1 🍍 + 1 🍌 + 1 🍊' },
  { icono: '🧺', nombre: 'Snack morado y verde', pedido: 'Two grapes and one pear', ids: ['grape','grape','pear'], pista: '2 🍇 + 1 🍐' },
  { icono: '🍰', nombre: 'Fruta para el pastel', pedido: 'Three cherries and one peach', ids: ['cherry','cherry','cherry','peach'], pista: '3 🍒 + 1 🍑' },
];
const reto = computed(() => retos[retoActual.value]);
const retoCorrecto = computed(() => comprobado.value && [...seleccionReto.value].sort().join('|') === [...reto.value.ids].sort().join('|'));
const totalAciertos = computed(() => aciertos.value.size);

function normalizar(texto) { return String(texto || '').toLowerCase().replace(/[^a-z]/g, ''); }
function escuchar(texto) { const referencia = props.items.find((item) => normalizar(item.texto_en) === normalizar(texto)); if (referencia?.audio_key) emit('reproducir', referencia); else emit('hablar', texto, 1); }
function cambiarCantidad(id, cambio) { const actual = canasta.value[id] || 0; canasta.value = { ...canasta.value, [id]: Math.max(0, Math.min(3, actual + cambio)) }; }
function agregarReto(id) { if (seleccionReto.value.length < reto.value.ids.length) seleccionReto.value = [...seleccionReto.value, id]; comprobado.value = false; }
function quitarReto(indice) { seleccionReto.value = seleccionReto.value.filter((_, posicion) => posicion !== indice); comprobado.value = false; }
function comprobarReto() { comprobado.value = true; if ([...seleccionReto.value].sort().join('|') === [...reto.value.ids].sort().join('|')) { const nuevos = new Set(aciertos.value); nuevos.add(retoActual.value); aciertos.value = nuevos; } }
function siguienteReto() { retoActual.value = (retoActual.value + 1) % retos.length; seleccionReto.value = []; comprobado.value = false; }
</script>

<template>
  <section class="fruit-lesson">
    <aside class="fruit-summary"><header><span>🍉</span><div><small>GUÍA DEL MERCADO</small><h2>Nombrá, describí y pedí frutas</h2></div></header><p>Para pedir una unidad usamos <b>a/an</b> o <b>one</b>; con dos o más usamos el plural: <i>one cherry → two cherries</i>.</p><div><article><b>-s</b><span>apple → apples</span></article><article><b>-es</b><span>peach → peaches</span></article><article><b>-y → -ies</b><span>cherry → cherries</span></article><article><b>Can I get…?</b><span>pedido natural y amable</span></article></div></aside>
    <nav class="fruit-tabs"><button v-for="numero in 3" :key="numero" :class="{ active: leccion === numero }" @click="leccion = numero"><b>0{{ numero }}</b><span>{{ numero === 1 ? 'Mercado' : numero === 2 ? 'Sabores y colores' : 'Prepará el pedido' }}</span><small>{{ numero === 1 ? 'Canasta + plurales' : numero === 2 ? 'Describí la fruta' : 'Reto de memoria' }}</small></button></nav>

    <section v-if="leccion === 1" class="fruit-panel"><header><small>FRUTAS 1</small><h3>Tu canasta en inglés</h3><p>Sumá hasta tres unidades de cada fruta y escuchá cómo cambia el pedido.</p></header><div class="fruit-market"><div class="fruit-shelf"><article v-for="fruta in frutas" :key="fruta.id"><button class="fruit-name" @click="escuchar(fruta.singular)"><span>{{ fruta.icono }}</span><b>{{ fruta.singular }}</b><small>{{ fruta.es }} 🔊</small></button><div><button @click="cambiarCantidad(fruta.id,-1)">−</button><strong>{{ canasta[fruta.id] || 0 }}</strong><button @click="cambiarCantidad(fruta.id,1)">+</button></div></article></div><aside class="basket-card"><span class="basket-icon">🧺</span><small>MI CANASTA · {{ totalCanasta }} PIEZAS</small><div class="basket-fruits"><template v-for="fruta in frutas" :key="fruta.id"><span v-for="n in (canasta[fruta.id] || 0)" :key="`${fruta.id}-${n}`">{{ fruta.icono }}</span></template></div><strong>{{ pedido }}</strong><button @click="escuchar(pedido)">🔊 Escuchar pedido</button></aside></div></section>

    <section v-else-if="leccion === 2" class="fruit-panel"><header><small>FRUTAS 2</small><h3>Laboratorio de sabores y colores</h3><p>Tocá una fruta para aprender a describirla, no solo nombrarla.</p></header><div class="taste-lab"><div class="taste-grid"><button v-for="fruta in frutas" :key="fruta.id" :class="{ active: frutaActiva === fruta.id }" @click="frutaActiva = fruta.id"><span>{{ fruta.icono }}</span><b>{{ fruta.singular }}</b></button></div><div class="taste-card"><span>{{ activa.icono }}</span><small>DESCRIBILA ASÍ</small><strong>{{ activa.singular }}</strong><p><b>Color:</b> {{ activa.color }}</p><p><b>Taste:</b> {{ activa.sabor }}</p><button @click="escuchar(`The ${activa.singular} is ${activa.sabor}.`)">🔊 Escuchar descripción</button></div></div><div class="fruit-sentence"><span>🗣️</span><p><b>My favorite fruit is {{ activa.singular }}.</b><button @click="escuchar(`My favorite fruit is ${activa.singular}.`)">🔊</button></p></div></section>

    <section v-else class="fruit-panel"><header class="fruit-challenge-head"><div><small>FRUTAS 3</small><h3>Prepará el pedido</h3><p>Escuchá o leé la orden y agregá las frutas correctas.</p></div><strong>{{ totalAciertos }}/{{ retos.length }}</strong></header><div class="order-game"><span class="order-icon">{{ reto.icono }}</span><small>{{ reto.nombre }}</small><button class="order-audio" @click="escuchar(reto.pedido)">🔊 {{ reto.pedido }}</button><p>Pista visual: {{ reto.pista }}</p><div class="order-tray"><button v-for="(id,indice) in seleccionReto" :key="`${id}-${indice}`" @click="quitarReto(indice)">{{ frutas.find((item)=>item.id===id).icono }}</button><span v-for="n in Math.max(0,reto.ids.length-seleccionReto.length)" :key="`empty-${n}`">＋</span></div><div class="order-fruits"><button v-for="fruta in frutas" :key="fruta.id" @click="agregarReto(fruta.id)"><span>{{ fruta.icono }}</span><small>{{ fruta.singular }}</small></button></div><button class="check-order" :disabled="seleccionReto.length !== reto.ids.length" @click="comprobarReto">Comprobar pedido</button><div v-if="comprobado" class="order-feedback" :class="retoCorrecto?'ok':'retry'"><b>{{ retoCorrecto?'✓ ¡Pedido listo!':'↻ Revisá cantidades y frutas' }}</b><span>{{ retoCorrecto?'El cliente recibió exactamente lo que pidió.':'Tocá una fruta de la bandeja para quitarla.' }}</span></div><button v-if="retoCorrecto" class="next-order" @click="siguienteReto">Siguiente pedido →</button></div></section>

    <button class="fruit-practice" :disabled="completado" @click="emit('practicar')">{{ completado ? '✓ Ejercicios ya acreditados' : 'Practicar ejercicios del workbook →' }}</button>
  </section>
</template>

