t-name small{font-size:.58rem;color:var(--color-texto-tenue)}.fruit-shelf article>div{width:100%;display:grid;grid-template-columns:1fr 1fr 1fr;background:#f4f7f0}.fruit-shelf article>div button{border:0;background:transparent;font-size:1rem}.fruit-shelf article>div strong{text-align:center}.basket-card{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:1rem;border-radius:16px;background:linear-gradient(145deg,#fff2ce,#eff8df);text-align:center}.basket-icon{font-size:2.6rem}.basket-card>small{font-size:.58rem;font-weight:900;color:#6e8e25}.basket-fruits{min-height:56px;font-size:1.45rem}.basket-card>strong{font:italic 1rem Georgia,serif}.basket-card>button,.taste-card button{margin-top:.6rem;border:0;border-radius:9px;background:#83a52f;color:#fff;padding:.5rem .7rem;font-weight:800}.taste-lab{display:grid;grid-template-columns:1.35fr .65fr;gap:1rem}.taste-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:.45rem}.taste-grid button{display:flex;flex-direction:column;align-items:center;padding:.55rem;border:1px solid var(--color-borde);border-radius:11px;background:#fff}.taste-grid button>span{font-size:1.9rem}.taste-grid button.active{border-color:#8daf37;background:#f4f9e8}.taste-card{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:1rem;border-radius:15px;background:linear-gradient(145deg,#ffe7e1,#f2f9df);text-align:center}.taste-card>span{font-size:3.2rem}.taste-card>small{font-size:.6rem;font-weight:900;color:#6e8e25}.taste-card>strong{font:italic 1.45rem Georgia,serif}.taste-card p{margin:.15rem;font-size:.72rem}.fruit-sentence{display:flex;align-items:center;gap:.55rem;margin-top:.8rem;padding:.65rem;border-radius:11px;background:#fff7e4}.fruit-sentence p{margin:0}.fruit-sentence button{border:0;background:transparent}.fruit-challenge-head{display:flex;justify-content:space-between}.fruit-challenge-head>strong{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#eff6dc;color:#6e8e25}.order-game{max-width:720px;margin:auto;padding:1.1rem;border-radius:17px;background:linear-gradient(145deg,#f5fae9,#fff2e7);text-align:center}.order-icon{display:block;font-size:2.8rem}.order-game>small{font-size:.6rem;font-weight:900;color:#6e8e25}.order-audio{display:block;margin:.4rem auto;border:0;background:transparent;font:italic 1.1rem Georgia,serif}.order-game>p{font-size:.7rem;color:var(--color-texto-tenue)}.order-tray{display:flex;justify-content:center;gap:.4rem;min-height:60px;padding:.55rem;border:2px dashed #c9d6a1;border-radius:13px;background:#fff}.order-tray button,.order-tray span{display:grid;place-items:center;width:43px;height:43px;border:0;border-radius:9px;background:#f5f8ef;font-size:1.7rem}.order-tray span{color:#b5c09b}.order-fruits{display:flex;justify-content:center;flex-wrap:wrap;gap:.35rem;margin:.7rem}.order-fruits button{display:flex;flex-direction:column;align-items:center;border:1px solid var(--color-borde);border-radius:9px;background:#fff;padding:.35rem}.order-fruits button span{font-size:1.35rem}.order-fruits small{font-size:.55rem}.check-order,.next-order{border:0;border-radius:9px;background:#83a52f;color:#fff;padding:.55rem .8rem;font-weight:800}.check-order:disabled{opacity:.4}.order-feedback{display:flex;flex-direction:column;margin-top:.65rem;padding:.65rem;border-radius:10px;font-size:.75rem;text-align:left}.order-feedback.ok{background:var(--color-verde-suave);color:#236843}.order-feedback.retry{background:#fff0ea;color:#984228}.next-order{display:block;margin:.65rem 0 0 auto}.fruit-practice{width:100%;padding:.8rem;border:0;border-radius:var(--radio-boton);background:#83a52f;color:#fff;font-weight:800}.fruit-practice:disabled{background:var(--color-verde)}
@media(max-width:800px){.fruit-market,.taste-lab{grid-template-columns:1fr}.fruit-shelf,.taste-grid{grid-template-columns:repeat(5,1fr)}.fruit-summary>div{grid-template-columns:1fr 1fr}}
@media(max-width:520px){.fruit-tabs{grid-template-columns:1fr}.fruit-shelf,.taste-grid{grid-template-columns:1fr 1fr}.fruit-summary>div{grid-template-columns:1fr}.fruit-panel{padding:.75rem}.order-tray{flex-wrap:wrap}}
</style>
